1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Three of this file's lookups can miss, and in every case a miss is the office
48	// declining rather than a bug: an uninsurable type, an uncovered item, an absent
49	// policy. Each caller names its own offender; this says once what they share — a
50	// miss is a domain error naming what was declined, never an undefined that
51	// travels on to surface later as a TypeError.
52	const foundOrThrow = <Found,>(found: Found | undefined, declined: string): Found => {
53	  if (found === undefined) {
54	    throw new Error(declined);
55	  }
56	  return found;
57	};
58	
59	// Both catalogue figures are read through this one row lookup, so an item's type
60	// is resolved against the catalogue in exactly one place — which makes it also
61	// the one place that can tell an insurable type from an uninsurable one. The
62	// catalogue does not merely price the types the MHPCO insures; it DEFINES them,
63	// so a missing row is not a lookup miss to defend against but the office
64	// declining the item, and it is reported in those terms.
65	const catalogueEntryFor = (item: Item) =>
66	  foundOrThrow(
67	    CATALOGUE[item.type],
68	    `the MHPCO does not insure items of type "${item.type}"`,
69	  );
70	
71	// Totalling a catalogue column over a list of items is the same operation on the
72	// premium side and the claim side; only the column differs. Naming it once keeps
73	// the two columns visibly separate — which is the point: the building-block
74	// discount rewrites the basePremium column and never touches insuranceValue.
75	const totalOfColumn =
76	  (columnOf: (item: Item) => number) =>
77	  (items: Item[]): number =>
78	    items.reduce((total, item) => total + columnOf(item), 0);
79	
80	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
81	
82	const BLOCK_SIZE = 3;
83	const BLOCK_BASE_PREMIUM = 60;
84	
85	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
86	  alikeItems.length === BLOCK_SIZE;
87	
88	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
89	
90	const CURSE_SURCHARGE_RATE = 0.5;
91	const HIGH_ENCHANTMENT_LEVEL = 5;
92	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
93	
94	const isCursed = (item: Item): boolean => item.cursed === true;
95	
96	// An unenchanted item is enchantment 0, so every threshold reads the level the
97	// same way. The MHPCO sets several enchantment thresholds for different rules;
98	// each names its own level and compares through here.
99	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
100	
101	const carriesEnchantmentSurcharge = (item: Item): boolean =>
102	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
103	
104	// A rate table prices one subject: every row whose risk applies contributes its
105	// rate, and the total is their sum. Both the item surcharges and the policy-wide
106	// modifiers are rate tables — they differ only in what they are applied to.
107	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
108	
109	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
110	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
111	
112	// Every item-specific surcharge is a rate on THAT item's base premium, charged
113	// when its risk applies. Adding a new one means adding a row here — nothing else.
114	const ITEM_SURCHARGES: RateTable<Item> = [
115	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
116	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
117	];
118	
119	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
120	
121	const itemSurchargesOn = (items: Item[]): number =>
122	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
123	
124	// Items of the same type are "alike"; each group is priced together so a
125	// building block can be recognised.
126	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
127	  ...items
128	    .reduce(
129	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
130	      new Map<string, Item[]>(),
131	    )
132	    .values(),
133	];
134	
135	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
136	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
137	
138	const policyBaseOf = (items: Item[]): number =>
139	  alikeItemGroupsIn(items).reduce(
140	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
141	    0,
142	  );
143	
144	// Rounding always favours the MHPCO. Which direction that is follows from which
145	// way the money moves: an amount the office RECEIVES is rounded up, an amount it
146	// PAYS is rounded down. Naming the two directions makes the rule one concept
147	// rather than two opposite-looking halves, and each call site says which kind of
148	// amount it holds — so the reason for the direction is in the code, not a comment.
149	const settledAsReceived = Math.ceil;
150	const settledAsPaid = Math.floor;
151	
152	const LOYALTY_YEARS = 2;
153	const LOYALTY_DISCOUNT_RATE = -0.2;
154	
155	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
156	
157	// Each item in a quote is treated as a first insurance regardless of customer
158	// history, so this surcharge is unconditional.
159	const appliesUnconditionally = (): boolean => true;
160	
161	const isLongStanding = ({ customer }: QuoteContext): boolean =>
162	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
163	
164	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
165	  precedingQuotes > 0;
166	
167	// A quote is priced from the customer plus its place in the scenario's history.
168	type QuoteContext = { customer: Customer; precedingQuotes: number };
169	
170	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
171	// base that already includes the item surcharges. Surcharges carry a positive
172	// rate, discounts a negative one. Adding a new one means adding a row here.
173	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
174	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
175	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
176	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
177	];
178	
179	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
180	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
181	
182	const quoteFor = (items: Item[], context: QuoteContext): Result => {
183	  const policyBase = policyBaseOf(items);
184	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
185	  return {
186	    premium: settledAsReceived(
187	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
188	    ),
189	  };
190	};
191	
192	const DEDUCTIBLE_PER_DAMAGE = 100;
193	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
194	
195	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
196	
197	// The insurance sum totals the value column over every insured item — one item,
198	// one row, no grouping. Blocks are a premium concept and cannot reach it.
199	const insuranceSumOf = totalOfColumn(insuranceValueOf);
200	
201	// A policy created by a quote step, tracked by that step's index so later claims
202	// can find it and draw down its cap.
203	type Policy = { items: Item[]; remainingCap: number };
204	
205	const policyFor = (items: Item[]): Policy => ({
206	  items,
207	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
208	});
209	
210	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
211	const HALF_REIMBURSEMENT_RATE = 0.5;
212	const FULL_REIMBURSEMENT_RATE = 1;
213	
214	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
215	// level: this one halves what a claim pays out, that one raises what a policy
216	// costs. They move independently — deliberately not shared.
217	const reimbursesOnlyHalf = (item: Item): boolean =>
218	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
219	
220	// How much of the damage the MHPCO reimburses, before the deductible bites.
221	const reimbursementRateFor = (item: Item): number =>
222	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
223	
224	// A damage names only an item TYPE, so it can identify no more than the type of
225	// the item it refers to — which is why this takes the type alone: the amount has
226	// no say in WHICH item answers for the damage. It returns the first insured item
227	// of that type as the representative whose traits price the damage.
228	//
229	// It is also the claim side's coverage guard. A type absent from the policy and
230	// a type the MHPCO does not insure at all are indistinguishable here, and both
231	// are declined by this one lookup: an uninsurable type could never have been
232	// quoted, so it can never appear among a policy's items.
233	//
234	// UNTESTED ASSUMPTION: that the first match is the right representative. Where a
235	// policy holds several alike items, the suite never distinguishes them — its only
236	// two-alike-items example insures two IDENTICAL swords, so first-match is
237	// unobservable there, and the spec offers no example pairing one type with
238	// DIFFERING enchantment or material. So this is an assumption the tests permit,
239	// not one they confirm. Should such an example appear, the damage would have to
240	// be matched to a specific item and this would be the place that changes.
241	const insuredItemOfType = (policy: Policy, itemType: string): Item =>
242	  foundOrThrow(
243	    policy.items.find((item) => item.type === itemType),
244	    `the policy does not cover an item of type "${itemType}"`,
245	  );
246	
247	// A damage is what the incident cost; an office cannot be owed money by a
248	// misfortune, so a negative amount is a malformed claim rather than a refund.
249	const damagedAmountOf = (damage: Damage): number => {
250	  if (damage.amount < 0) {
251	    throw new Error(`a damage cannot be negative, but was ${damage.amount}`);
252	  }
253	  return damage.amount;
254	};
255	
256	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
257	  damagedAmountOf(damage) *
258	  reimbursementRateFor(insuredItemOfType(policy, damage.itemType));
259	
260	// The deductible bites once per damage, after the reimbursement rate is applied
261	// — never the other way round, which would pay out more.
262	const payoutForDamage = (damage: Damage, policy: Policy): number =>
263	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
264	
265	// How many times each type appears in a list of types. The file's other
266	// by-type reading, alikeItemGroupsIn, collects the items themselves because the
267	// premium side prices them; here only the tally matters.
268	const countByType = (types: string[]): Map<string, number> =>
269	  types.reduce(
270	    (counts, type) => counts.set(type, (counts.get(type) ?? 0) + 1),
271	    new Map<string, number>(),
272	  );
273	
274	// A damage entry stands for one damaged item, so an incident cannot name more
275	// damages of a type than the policy insures of that type. Asking for the
276	// overclaimed type — rather than testing each damage in turn — puts this beside
277	// the file's other three misses: a lookup that yields nothing when all is well
278	// and names the offender when it is not.
279	const overclaimedTypeIn = (incident: Incident, policy: Policy): string | undefined => {
280	  const insuredCounts = countByType(policy.items.map((item) => item.type));
281	  return [...countByType(incident.damages.map((damage) => damage.itemType))]
282	    .filter(([type, damaged]) => damaged > (insuredCounts.get(type) ?? 0))
283	    .map(([type]) => type)
284	    .at(0);
285	};
286	
287	// The whole claim is rejected rather than settled in part, so the overclaim is
288	// checked before any damage is priced.
289	const rejectOverclaimedTypes = (incident: Incident, policy: Policy): void => {
290	  const overclaimed = overclaimedTypeIn(incident, policy);
291	  if (overclaimed !== undefined) {
292	    throw new Error(
293	      `the policy does not cover that many items of type "${overclaimed}"`,
294	    );
295	  }
296	};
297	
298	// One incident can damage several items; each damage is settled on its own
299	// (and so bears its own deductible), and the incident pays out their sum.
300	const payoutForIncident = (incident: Incident, policy: Policy): number => {
301	  rejectOverclaimedTypes(incident, policy);
302	  return incident.damages.reduce(
303	    (sum, damage) => sum + payoutForDamage(damage, policy),
304	    0,
305	  );
306	};
307	
308	// A payout is drawn from the policy's cap, leaving less for later claims.
309	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
310	  ...policy,
311	  remainingCap: policy.remainingCap - payout,
312	});
313	
314	// The policy pays no more than the cap it has left, however large the damage.
315	const payoutWithinCapOf = (policy: Policy, desiredPayout: number): number =>
316	  Math.min(desiredPayout, policy.remainingCap);
317	
318	// Settling a claim pays out and draws the cap down by the same amount, so the
319	// result the customer sees is the payout plus the cap that payout left behind.
320	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
321	  const payout = settledAsPaid(
322	    payoutWithinCapOf(policy, payoutForIncident(incident, policy)),
323	  );
324	  const settledPolicy = capDrawnDownBy(policy, payout);
325	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
326	};
327	
328	// What the scenario has accumulated before the current step: the results so far,
329	// the history a quote is priced against, and the policies earlier quotes created.
330	type ScenarioState = {
331	  results: Result[];
332	  precedingQuotes: number;
333	  policies: Record<number, Policy>;
334	};
335	
336	const INITIAL_SCENARIO_STATE: ScenarioState = {
337	  results: [],
338	  precedingQuotes: 0,
339	  policies: {},
340	};
341	
342	// Every step reports exactly one result and leaves one policy at its index —
343	// the two things both step kinds always do. Recording them is named once here
344	// rather than rebuilt in each of them.
345	const withStepRecorded = (
346	  state: ScenarioState,
347	  result: Result,
348	  policyIndex: number,
349	  policy: Policy,
350	): ScenarioState => ({
351	  ...state,
352	  results: [...state.results, result],
353	  policies: { ...state.policies, [policyIndex]: policy },
354	});
355	
356	const afterQuote = (
357	  state: ScenarioState,
358	  items: Item[],
359	  customer: Customer,
360	  stepIndex: number,
361	): ScenarioState => ({
362	  ...withStepRecorded(
363	    state,
364	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
365	    stepIndex,
366	    policyFor(items),
367	  ),
368	  precedingQuotes: state.precedingQuotes + 1,
369	});
370	
371	// A claim names the quote step whose policy it draws on. Only a quote creates a
372	// policy, so an index no quote reached is the claim naming a policy that does
373	// not exist.
374	const policyAt = (state: ScenarioState, policyIndex: number): Policy =>
375	  foundOrThrow(
376	    state.policies[policyIndex],
377	    `there is no policy at step ${policyIndex}`,
378	  );
379	
380	const afterClaim = (
381	  state: ScenarioState,
382	  policyIndex: number,
383	  incident: Incident,
384	): ScenarioState => {
385	  const [result, settledPolicy] = claimFor(incident, policyAt(state, policyIndex));
386	  return withStepRecorded(state, result, policyIndex, settledPolicy);
387	};
388	
389	const afterStep = (
390	  state: ScenarioState,
391	  step: Step,
392	  customer: Customer,
393	  stepIndex: number,
394	): ScenarioState =>
395	  step.op === "quote"
396	    ? afterQuote(state, step.items, customer, stepIndex)
397	    : afterClaim(state, step.policy, step.incident);
398	
399	export const runScenario = (scenario: Scenario): { results: Result[] } => {
400	  const { results } = scenario.steps.reduce(
401	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
402	    INITIAL_SCENARIO_STATE,
403	  );
404	  return { results };
405	};
406

